#include "aob/dsp.hpp"
#include <algorithm>
#include <cmath>
namespace aob{static float g(float d){return std::pow(10.f,d/20.f);}void DspEngine::set_preset(Preset p){s_=DspSettings{};switch(p){case Preset::Original:s_.enabled=false;break;case Preset::Music:s_.bass_db=2;s_.treble_db=1;break;case Preset::Movie:s_.bass_db=3;s_.eq_db={2,1,0,-1,0,2,3,2,1,2};break;case Preset::Gaming:s_.eq_db={1,1,0,1,2,2,1,1,2,1};break;case Preset::Voice:s_.eq_db={-2,-2,-1,1,3,4,3,1,0,-1};break;case Preset::BassBoost:s_.bass_db=6;break;case Preset::Loudness:s_.loudness=.65f;s_.output_db=2;break;case Preset::AobMax:s_.bass_db=4;s_.treble_db=2;s_.compressor=.45f;s_.output_db=3;break;default:break;}}void DspEngine::process(float*x,size_t n,size_t ch){if(!s_.enabled||!x||!ch)return;float k=g(s_.preamp_db+s_.output_db),lim=g(s_.limiter_db);for(size_t i=0;i<n*ch;i++){float v=x[i]*k;if(s_.compressor>0&&std::abs(v)>.7f){float a=std::abs(v);v=(v<0?-1:1)*(.7f+(a-.7f)*(1-s_.compressor));}x[i]=std::clamp(v,-lim,lim);}}}